fn cmd_mcp(args: McpArgs) -> Result<(), Box<dyn std::error::Error>> {
    match args.args.first().map(String::as_str) {
        Some("status") if args.args.len() == 1 => cmd_mcp_status(false),
        Some("doctor") if args.args.len() == 1 => cmd_mcp_status(true),
        Some("config") => {
            let config = McpConfigCli::try_parse_from(args.args)?;
            cmd_mcp_config(McpConfigArgs {
                command: config.command,
            })
        }
        _ => {
            let code = target::cli::mcp::run(&args.args)?;
            if code != 0 {
                std::process::exit(code);
            }
            Ok(())
        }
    }
}

fn cmd_mcp_status(doctor: bool) -> Result<(), Box<dyn std::error::Error>> {
    let paths = mcp_paths_for_cwd()?;
    println!("MCP support status (static checks only)");
    println!(
        "pi on PATH: {}",
        if command_exists("pi") { "yes" } else { "no" }
    );
    println!("native config order (project file requires Pi trust):");
    for path in paths.legacy_paths().into_iter().filter(|p| p.exists()) {
        println!(
            "warning: {} is NOT loaded by native Pi; migrate deliberately using docs/mcp-native.md",
            path.display()
        );
    }
    for path in paths.discovery_order() {
        if path.exists() {
            match target::mcp_config::load_or_empty(&path).and_then(|value| {
                target::mcp_config::validate_value(&value).map(|warnings| (value, warnings))
            }) {
                Ok((value, warnings)) => {
                    let names = target::mcp_config::server_names(&value);
                    println!("  {}: ok ({} servers)", path.display(), names.len());
                    if !names.is_empty() {
                        println!("    servers: {}", names.join(", "));
                    }
                    for warning in warnings {
                        println!("    warning: {warning}");
                    }
                }
                Err(err) => println!("  {}: invalid ({err})", path.display()),
            }
        } else {
            println!("  {}: missing", path.display());
        }
    }
    if doctor {
        println!("next steps:");
        if !command_exists("pi") {
            println!("  - install pi or add it to PATH");
        }
        println!("  - explicitly connect/check servers: opi mcp list");
        println!("  - add stdio server: opi mcp config add symbol-index --stdio symbol-index");
    }
    Ok(())
}

fn cmd_mcp_config(args: McpConfigArgs) -> Result<(), Box<dyn std::error::Error>> {
    let cwd = std::env::current_dir()?;
    match args.command {
        McpConfigCommand::Paths => {
            let paths = mcp_paths_for_cwd()?;
            println!("legacy XDG (not loaded): {}", paths.xdg_config.display());
            println!("user: {}", paths.user_agent.display());
            println!(
                "legacy .mcp.json (not loaded): {}",
                paths.project_dot_mcp.display()
            );
            println!("project .pi/mcp.json: {}", paths.project_pi.display());
            println!("default write target: {}", paths.user_agent.display());
            println!("project write target: {}", paths.project_pi.display());
        }
        McpConfigCommand::Show(target) => {
            let path = target::mcp_config::target_path(target.project, &cwd);
            let value = target::mcp_config::load_or_empty(&path)?;
            println!("{}", serde_json::to_string_pretty(&value)?);
        }
        McpConfigCommand::Validate(validate) => {
            let paths = mcp_paths_for_cwd()?;
            let selected = if validate.project {
                vec![paths.project_pi]
            } else if validate.user {
                vec![paths.user_agent]
            } else {
                paths.discovery_order()
            };
            let mut failed = false;
            for path in selected {
                if !path.exists() {
                    println!("{}: missing", path.display());
                    continue;
                }
                match target::mcp_config::load_or_empty(&path)
                    .and_then(|value| target::mcp_config::validate_value(&value))
                {
                    Ok(warnings) => {
                        println!(
                            "{}: structurally valid (not a native schema/connection check)",
                            path.display()
                        );
                        for warning in warnings {
                            println!("  warning: {warning}");
                        }
                    }
                    Err(err) => {
                        failed = true;
                        println!("{}: invalid: {err}", path.display());
                    }
                }
            }
            if failed {
                return Err(io::Error::new(
                    io::ErrorKind::InvalidData,
                    "one or more MCP config files are invalid",
                )
                .into());
            }
        }
        McpConfigCommand::List(target) => {
            let path = target::mcp_config::target_path(target.project, &cwd);
            let value = target::mcp_config::load_or_empty(&path)?;
            for name in target::mcp_config::server_names(&value) {
                println!("{name}");
            }
        }
        McpConfigCommand::Add(add) => {
            let mut tail = vec!["add".to_string(), add.name];
            if add.project {
                tail.push("--local".into());
            }
            for (flag, values) in [("--env", add.env), ("--header", add.header)] {
                for value in values {
                    tail.extend([flag.into(), value]);
                }
            }
            for (flag, value) in [
                ("--url", add.url),
                ("--cwd", add.cwd),
                ("--bearer-token-env-var", add.bearer_token_env),
            ] {
                if let Some(value) = value {
                    tail.extend([flag.into(), value]);
                }
            }
            if let Some(command) = add.stdio {
                tail.extend(["--".into(), command]);
                tail.extend(add.args);
            } else if !add.args.is_empty() {
                return Err("--arg requires --stdio".into());
            }
            let code = target::cli::mcp::run(&tail)?;
            if code != 0 {
                std::process::exit(code);
            }
        }
        McpConfigCommand::Remove(remove) => {
            let mut tail = vec!["remove".into(), remove.name];
            if remove.project {
                tail.push("--local".into());
            }
            let code = target::cli::mcp::run(&tail)?;
            if code != 0 {
                std::process::exit(code);
            }
        }
    }
    Ok(())
}
